FUNCTION_BLOCK FB_MechanicalArmControl
VAR_INPUT
 ManualMode : BOOL;
 ...
END_VAR
VAR_OUTPUT
 MoveDown : BOOL;
 ...
END_VAR
VAR
 prevStart : BOOL;
 startEdge : BOOL;
 currentStep : INT := 0;
 cycleRunning : BOOL := FALSE;
 stepComplete : BOOL;
 prevManual : BOOL;
 prevSingleStep : BOOL;
 prevSingleCycle : BOOL;
 prevContinuous : BOOL;
END_VAR

BEGIN
// Edge
 startEdge := Start AND NOT prevStart AND EmergencyStop;
 // reset outputs
 MoveDown := FALSE; ...
 // manual
 IF ManualMode THEN
   IF NOT prevManual THEN
     currentStep := 0;
     cycleRunning := FALSE;
   END_IF;
   IF DownButton AND NOT DownLimitSwitch THEN MoveDown := TRUE; END_IF;
   IF UpButton AND NOT UpLimitSwitch THEN MoveUp := TRUE; END_IF;
   IF LeftButton AND NOT LeftLimitSwitch THEN MoveLeft := TRUE; END_IF;
   IF RightButton AND NOT RightLimitSwitch THEN MoveRight := TRUE; END_IF;
   IF GripButton AND NOT GripLimitSwitch THEN ActivateGrip := TRUE; END_IF;
   IF ReleaseButton AND NOT ReleaseLimitSwitch THEN ActivateRelease := TRUE; END_IF;
 ELSIF SingleStepMode THEN
   IF NOT prevSingleStep THEN
      currentStep := 0;
   END_IF;
   IF startEdge THEN
      IF currentStep = 0 THEN
         currentStep := 1;
      ELSIF currentStep = 1 AND DownLimitSwitch THEN
         currentStep := 2;
      ... 
      ELSIF currentStep = 8 AND LeftLimitSwitch THEN
         currentStep := 1; // begin again
      END_IF;
   END_IF;
   CASE currentStep OF
     1: IF NOT DownLimitSwitch THEN MoveDown:=TRUE; END_IF;
     2: IF NOT GripLimitSwitch THEN ActivateGrip:=TRUE; END_IF;
     3: IF NOT UpLimitSwitch THEN MoveUp:=TRUE; END_IF;
     4: IF NOT RightLimitSwitch THEN MoveRight:=TRUE; END_IF;
     5: IF NOT DownLimitSwitch THEN MoveDown:=TRUE; END_IF;
     6: IF NOT ReleaseLimitSwitch THEN ActivateRelease:=TRUE; END_IF;
     7: IF NOT UpLimitSwitch THEN MoveUp:=TRUE; END_IF;
     8: IF NOT LeftLimitSwitch THEN MoveLeft:=TRUE; END_IF;
   END_CASE;
 ELSIF SingleCycleMode OR ContinuousMode THEN
   IF (SingleCycleMode AND NOT prevSingleCycle) OR (ContinuousMode AND NOT prevContinuous) THEN
     currentStep := 0;
     cycleRunning := FALSE;
   END_IF;
   IF startEdge AND NOT cycleRunning THEN
      cycleRunning := TRUE;
      currentStep := 1;
   END_IF;
   IF cycleRunning AND EmergencyStop THEN
      stepComplete := FALSE;
      CASE currentStep OF
         1: MoveDown := TRUE; stepComplete := DownLimitSwitch;
         2: ActivateGrip := TRUE; stepComplete := GripLimitSwitch;
         3: MoveUp := TRUE; stepComplete := UpLimitSwitch;
         4: MoveRight := TRUE; stepComplete := RightLimitSwitch;
         5: MoveDown := TRUE; stepComplete := DownLimitSwitch;
         6: ActivateRelease := TRUE; stepComplete := ReleaseLimitSwitch;
         7: MoveUp := TRUE; stepComplete := UpLimitSwitch;
         8: MoveLeft := TRUE; stepComplete := LeftLimitSwitch;
         ELSE
           stepComplete := FALSE;
      END_CASE;
      IF stepComplete THEN
         IF currentStep < 8 THEN
            currentStep := currentStep + 1;
         ELSIF SingleCycleMode THEN
            cycleRunning := FALSE;
            currentStep := 0;
         ELSE // ContinuousMode
            currentStep := 1;
         END_IF;
      END_IF;
   END_IF;
 END_IF;

 // latch previous modes and start
 prevStart := Start;
 prevManual := ManualMode;
 prevSingleStep := SingleStepMode;
 prevSingleCycle := SingleCycleMode;
 prevContinuous := ContinuousMode;

 // e-stop override
 IF NOT EmergencyStop THEN
    MoveDown := FALSE; ...
 END_IF;
END_FUNCTION_BLOCK

